"""R4.3.1a: a roll-up is regenerated by the write that invalidates it.

Roll-ups are the one piece of derived data living IN the source of truth, so
C3's "everything derived is disposable" does not protect them: a stale
roll-up is a wrong answer in a committed file that the user reads.
"""
import pytest
from conftest import snapshot

from brain import commands as c
from brain import git, grammar as gr, rollup, tree


def _run(root, line):
    return c.execute(root, gr.parse_line(line))


def _commits(root):
    return int(git.run(["rev-list", "--count", "HEAD"], root))


def _rollup(root):
    body = (root / "programs" / "cloud-migration.md").read_text(encoding="utf-8")
    return body.split("## Roll-up")[1].split("\n## ")[0]


def test_a_project_write_updates_its_program_in_the_same_commit(brain_repo):
    """R4.3.1a's whole point: one write, one commit, both files."""
    before = _commits(brain_repo)
    _run(brain_repo, "set acme-migration status -- blocked")
    assert _commits(brain_repo) == before + 1, "one write must stay one commit"
    touched = git.run(["show", "--name-only", "--format=", "HEAD"], brain_repo)
    assert "projects/acme-migration.md" in touched
    assert "programs/cloud-migration.md" in touched
    assert "blocked" in _rollup(brain_repo)


def test_the_regenerated_value_is_the_one_just_written(brain_repo):
    """The staleness this was written to catch: `perform` read the tree's
    cached entity, whose `.status`/`.health` are `_read()` snapshots taken at
    construction. Reading `known_paths()` before the verb ran meant the
    refresh never happened on the single-verb path, so the roll-up showed the
    PREVIOUS value and only caught up on the next write."""
    _run(brain_repo, "set acme-migration health -- red")
    row = [l for l in _rollup(brain_repo).splitlines() if "acme-migration" in l]
    assert row and "red" in row[0], row


def test_a_project_in_no_program_widens_nothing(brain_repo):
    """R11.2: a commit must not grow for a project that no roll-up reports.
    `q4-budget` declares no program."""
    _run(brain_repo, "set q4-budget status -- active")
    touched = git.run(["show", "--name-only", "--format=", "HEAD"],
                      brain_repo).split()
    assert touched == ["projects/q4-budget.md"], touched


def test_regeneration_stays_inside_the_rollup_section(brain_repo):
    """R5.1. The program's Summary and Log must not move."""
    before = snapshot(brain_repo)
    _run(brain_repo, "set acme-migration status -- blocked")
    after = snapshot(brain_repo)
    changed = {i for i, (a, b) in enumerate(
        zip(before["programs/cloud-migration.md"],
            after["programs/cloud-migration.md"])) if a != b}
    inside, seen = set(), False
    for i, line in enumerate(after["programs/cloud-migration.md"]):
        if line.startswith("## "):
            seen = line.strip() == "## Roll-up"
            continue
        if seen:
            inside.add(i)
    assert changed and changed <= inside, sorted(changed - inside)


def test_a_batch_rewrites_the_program_once(brain_repo):
    """Refresh runs once for the whole batch, not per line - otherwise a
    three-project batch puts three rewrites of one file in one commit."""
    before = _commits(brain_repo)
    c.apply_batch(brain_repo,
                  "set acme-migration status -- blocked\n"
                  "set acme-migration health -- red\n")
    assert _commits(brain_repo) == before + 1
    row = [l for l in _rollup(brain_repo).splitlines() if "acme-migration" in l]
    assert "blocked" in row[0] and "red" in row[0], row


def test_the_due_column_carries_the_next_open_actions_due_date(brain_repo):
    """§4.3: the roll-up's `Due` column is the next OPEN action's due date,
    blank when it has none - not the project's own `due:` field, which is a
    separate value (the fixture's acme-migration carries both, and they
    differ, so a correct implementation cannot pass by accident)."""
    _run(brain_repo, "set acme-migration status -- active")   # trigger a rewrite
    row = [l for l in _rollup(brain_repo).splitlines() if "acme-migration" in l][0]
    assert "| 2026-09-11 |" in row, row
    assert "2026-10-15" not in row, "the project's own due:, not the action's, leaked in"
    _run(brain_repo, "link q4-budget cloud-migration")
    row2 = [l for l in _rollup(brain_repo).splitlines() if "q4-budget" in l][0]
    cells = [c.strip() for c in row2.strip("|").split("|")]
    assert cells[-1] == "", "no open action has a due date, so Due must be blank: {!r}".format(row2)


def test_a_pipe_in_an_action_cannot_forge_a_column(brain_repo):
    """The characteristic defect, twenty-sixth guard. The `Next` cell carries
    the user's own action text (R4.6.1), and a `|` in it would forge a table
    column that `brain check` and the TUI would both read as structure."""
    # A fresh project, because `## Next actions` APPENDS (R4.2.1) - against
    # the fixture the Next cell shows its pre-existing first action, so the
    # piped text never reached the cell and this test passed with the escape
    # removed.
    _run(brain_repo, "new project -- Pipe probe")
    _run(brain_repo, "link pipe-probe cloud-migration")
    _run(brain_repo, "todo pipe-probe -- ship | rollback | decide")
    row = [l for l in _rollup(brain_repo).splitlines() if "pipe-probe" in l][0]
    assert "ship" in row, "the action must actually reach the Next cell"
    # §4.3 added a Due column, so a correct row now carries seven pipes
    # (six cells); a forged column from the action's own text would add one.
    assert row.count("|") == 7, "a forged column: {!r}".format(row)


def test_build_repairs_a_hand_edited_rollup(brain_repo):
    """`brain build` exists for a brain edited outside brain (R4.3.1a)."""
    path = brain_repo / "programs" / "cloud-migration.md"
    _run(brain_repo, "set acme-migration status -- active")

    # Corrupt ONLY the roll-up. A blanket replace also hits the program's own
    # `status:` front matter, which `build` has no business rewriting - so the
    # assertion would fail on a correct implementation.
    head, rest = path.read_text(encoding="utf-8").split("## Roll-up", 1)
    body, tail = rest.split("\n## ", 1)
    path.write_text(head + "## Roll-up" + body.replace("active", "WRONGSTATUS")
                    + "\n## " + tail, encoding="utf-8")

    _run(brain_repo, "build")
    assert "WRONGSTATUS" not in path.read_text(encoding="utf-8")
    assert "| acme-migration | active |" in _rollup(brain_repo)


def test_moving_a_project_between_programs_refreshes_both(brain_repo):
    """H1 from the milestone-4 final review: `programs_touched` read the
    project's `program:` AFTER the write, so only the destination was
    refreshed and the source went on listing a project it no longer had -
    both roll-ups claimed it. That is R4.3.1a's exact failure."""
    _run(brain_repo, "new program -- Second wave")
    _run(brain_repo, "link acme-migration second-wave")
    old = (brain_repo / "programs" / "cloud-migration.md").read_text(encoding="utf-8")
    new = (brain_repo / "programs" / "second-wave.md").read_text(encoding="utf-8")
    assert "acme-migration" not in old.split("## Roll-up")[1].split("\n## ")[0]
    assert "| acme-migration |" in new
    touched = git.run(["show", "--name-only", "--format=", "HEAD"], brain_repo)
    assert "programs/cloud-migration.md" in touched, "the OLD program must be in the commit"
    assert "programs/second-wave.md" in touched
